// Flag coins whose 24h price moved beyond the threshold, ranked by size of move
const cfg = $('Configuration').first().json;
const threshold = cfg.spikeThresholdPercent || 5;
const maxAlerts = cfg.maxAlerts || 8;
const coins = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) { for (const c of j) coins.push(c); }
  else if (j && typeof j === 'object' && j.symbol) coins.push(j);
  else if (j && Array.isArray(j.data)) { for (const c of j.data) coins.push(c); }
}
const movers = [];
for (const c of coins) {
  const change = c.price_change_percentage_24h;
  if (typeof change !== 'number' || Math.abs(change) < threshold) continue;
  movers.push({
    name: String(c.name || '').replace(/[<\>\[\]]/g, ''),
    symbol: String(c.symbol || '').toUpperCase(),
    price: c.current_price,
    change24h: Math.round(change * 100) / 100,
    marketCap: c.market_cap || 0
  });
}
movers.sort((a, b) => Math.abs(b.change24h) - Math.abs(a.change24h));
return movers.slice(0, maxAlerts).map((m) => ({ json: m }));

// Format the detected movers for the AI analyst
const movers = $input.all().map((i) => i.json);
const lines = movers.map((m) => m.name + ' (' + m.symbol + '): $' + m.price + ', ' + m.change24h + '% in 24h').join('\n');
return [{ json: { moversText: lines, moverCount: movers.length } }];

// Combine the detected movers and the AI take into a Telegram Markdown alert
const movers = $('Detect Price Spikes').all().map((i) => i.json);
const raw = $input.first().json;
const take = (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content || '').trim();
const cfg = $('Configuration').first().json;
const today = new Date().toISOString().slice(0, 10);
const lines = [];
lines.push(cfg.alertTitle + ' - ' + today);
lines.push('');
lines.push('*AI market take*');
lines.push(take || '_Market take unavailable._');
lines.push('');
lines.push('*Biggest movers (24h)*');
movers.forEach((m) => {
  const arrow = m.change24h >= 0 ? '^' : 'v';
  lines.push(arrow + ' *' + m.name + '* (' + m.symbol + '): $' + m.price + ' (' + m.change24h + '%)');
});
return [{ json: { message: lines.join('\n') } }];
